/////////////////////////////////
// cp_trigger_changingtos_sti
//   Trigger STIP when enabling SIE in S-mode
//   Set STIP in M-mode, enter S-mode with SIE=0, then set sstatus.SIE=1
/////////////////////////////////

# M-mode setup
  CSRW(mie, zero)
  csrci mstatus, 8
  csrci mstatus, 2
  # Clear supervisor timer interrupt
  BEQZ x0, 1f # If STCE=0, use legacy method

  # Sstc method: Write stimecmp = -1 (max value)
  LI(x13, -1)
  csrw stimecmp, x13
#if __riscv_xlen == 32
  csrw stimecmph, x13
#endif
  j 2f

