// skip clearing interrupt if RVMODEL_MTIMECMP_ADDRESS is not defined
#ifdef RVMODEL_MTIMECMP_ADDRESS
  LA(x8, RVMODEL_MTIMECMP_ADDRESS)
  SREG x13, 0(x8)
#if __riscv_xlen == 32
  sw x13, 4(x8)
#endif
#endif
  LI(x15, 0x222)
  CSRW(mideleg, x15)
  LI(x15, -1)
  CSRW(mie, x15)
#ifndef SM1P11P0_SUPPORTED
  CSRR x10, menvcfg
#if __riscv_xlen == 64
    srli x10, x10, 63
#else
    srli x10, x10, 31
#endif
  andi x10, x10, 0x1
#endif
