# Test: MIE=0, SIE=0, mideleg=zeros, MTIE=0, mode=Smode
  RVTEST_GOTO_MMODE
  CSRW(mie, zero)
  csrci mstatus, 8
  csrci mstatus, 2
  LI(x15, 0x2)
  CSRC(mip, x15)
  RVTEST_CLR_MSW_INT
  # Clear supervisor timer interrupt
  BEQZ x0, 1f # If STCE=0, use legacy method

  # Sstc method: Write stimecmp = -1 (max value)
  LI(x14, -1)
  csrw stimecmp, x14
#if __riscv_xlen == 32
  csrw stimecmph, x14
#endif
  j 2f

1: # Legacy method: Clear mip.STIP (must be in M-mode)
  LI(x14, 0x20)
  csrrc x14, mip, x14

