/////////////////////////////////
// cp_vectored_m
//   Test vectored interrupts in M-mode
//   S-interrupts with mideleg=0 fire in M-mode
/////////////////////////////////


# Test vectored M-mode: ssip
  RVTEST_GOTO_MMODE
  CSRW(mie, zero)
  csrci mstatus, 8
  LI(x13, 0x2)
  CSRC(mip, x13)
  RVTEST_CLR_SEXT_INT
  # Clear supervisor timer interrupt
  BEQZ x0, 1f # If STCE=0, use legacy method

  # Sstc method: Write stimecmp = -1 (max value)
  LI(x14, -1)
  csrw stimecmp, x14
#if __riscv_xlen == 32
  csrw stimecmph, x14
#endif
  j 2f

1: # Legacy method: Clear mip.STIP (must be in M-mode)
  LI(x14, 0x20)
  csrrc x14, mip, x14

2: # Continue
  CSRR x13, mtvec
  SRLI x13, x13, 2
  SLLI x13, x13, 2
  ADDI x13, x13, 1
  CSRW(mtvec, x13)
  CSRW(mideleg, zero)
  LI(x13, 0x222)
  CSRW(mie, x13)
  csrsi mstatus, 8
InterruptsS_S_cg_cp_vectored_m_vectored_ssip:
  LI(x13, 0x2)
  CSRS(mip, x13)
  RVTEST_IDLE_FOR_INTERRUPT(x13)
  RVTEST_GOTO_MMODE
  csrci mstatus, 8
  csrci mstatus, 2
  CSRW(mideleg, zero)
  CSRW(mie, zero)
  LI(x13, 0x2)
  CSRC(mip, x13)

