/////////////////////////////////
// cp_wfi_u
//   Test WFI from U-mode
//   Cross: MIE={0,1} × SIE={0,1} × mideleg={0,0x222} × TW={0,1}
/////////////////////////////////


# Test: MIE=0, SIE=0, mideleg=nodeleg, TW=0
  RVTEST_GOTO_MMODE
  CSRW(mie, zero)
  csrci mstatus, 8
  csrci mstatus, 2
  # Clear machine timer interrupt
  LI(x14, -1)
// skip clearing interrupt if RVMODEL_MTIMECMP_ADDRESS is not defined
#ifdef RVMODEL_MTIMECMP_ADDRESS
  LA(x15, RVMODEL_MTIMECMP_ADDRESS)
  SREG x14, 0(x15)
#if __riscv_xlen == 32
  sw x14, 4(x15)
#endif
#endif
  CSRW(mideleg, zero)
  LI(x11, 0x200000)
  CSRC(mstatus, x11)
  LI(x11, 0x80)
  CSRW(mie, x11)
  # Cause machine timer interrupt soon if supported
#ifdef RVMODEL_MTIME_ADDRESS
  LA(x10, RVMODEL_MTIME_ADDRESS)
  LA(x15, RVMODEL_MTIMECMP_ADDRESS)
#if __riscv_xlen == 64
# Read current time and add delay
  LI(x13, RVMODEL_TIMER_INT_SOON_DELAY)
  LREG x14, 0(x10)
  add x14, x14, x13
  SREG x14, 0(x15)
#elif __riscv_xlen == 32
  LI(x8, RVMODEL_TIMER_INT_SOON_DELAY)
# Read current time (64-bit on RV32)
  lw x14, 0(x10)
  lw x13, 4(x10)
# Add delay to 64-bit value
  add x11, x14, x8
  sltu x8, x11, x14
  add x13, x13, x8
# Per RISC-V Spec 3.2.1: Write sequence to prevent spurious interrupt
  LI(x14, -1)
  sw x14, 0(x15)
  sw x13, 4(x15)
  sw x11, 0(x15)
#endif
#endif
InterruptsS_S_cg_cp_wfi_u_mie0_sie0_nodeleg_tw0:
  RVTEST_GOTO_LOWER_MODE Umode
    wfi
