# Test: MIE=0, SIE=0
  RVTEST_GOTO_MMODE
  CSRW(mie, zero)
  csrci mstatus, 8
  csrci mstatus, 2
  LI(x14, 0x2)
  CSRC(mip, x14)
  RVTEST_CLR_MSW_INT
  # Clear supervisor timer interrupt
  BEQZ x0, 1f # If STCE=0, use legacy method

  # Sstc method: Write stimecmp = -1 (max value)
  LI(x8, -1)
  csrw stimecmp, x8
#if __riscv_xlen == 32
  csrw stimecmph, x8
#endif
  j 2f

